import{_ as i,o as t,c as a,a3 as s}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"Experimental Report on Logistics Anomalies","description":"","frontmatter":{"translationSource":{"title":"物流异常实验报告","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vgX94GkmwkrVct7UWZN3bJ","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/reactor-crucible-logistics-anomalies"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/reactor-crucible-logistics-anomalies"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/reactor-crucible-logistics-anomalies"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/reactor-crucible-logistics-anomalies"}]]},"headers":[],"relativePath":"reactor-crucible-logistics-anomalies.md","filePath":"logistics/src/page-vgX94GkmwkrVct7UWZN3bJ.md"}'),n={name:"reactor-crucible-logistics-anomalies.md"};function o(r,e,c,p,l,d){return t(),a("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><h1 id="experimental-report-on-logistics-anomalies" tabindex="-1">Experimental Report on Logistics Anomalies <a class="header-anchor" href="#experimental-report-on-logistics-anomalies" aria-label="Permalink to &quot;Experimental Report on Logistics Anomalies&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-08T14-43-43-693Z-b04528fe" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-08. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-08T14:43:45.228Z">2026-11-08</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>vgX94GkmwkrVct7UWZN3bJ</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vgX94GkmwkrVct7UWZN3bJ" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-h3GMS2ZHH1VcDcEQRt1n2o"></span></p><h2 id="preliminary-experiments-on-reaction-tank-expanded-reaction-tank-output-priority" tabindex="-1">Preliminary Experiments on Reaction-Tank / Expanded Reaction-Tank Output Priority <a class="header-anchor" href="#preliminary-experiments-on-reaction-tank-expanded-reaction-tank-output-priority" aria-label="Permalink to &quot;Preliminary Experiments on Reaction-Tank / Expanded Reaction-Tank Output Priority&quot;">​</a></h2><p>When a crucible reacts and its output ports are configured, two cases arise: a product outputs first and only overflows into the next reaction; or it enters the next reaction first and only overflows into output.</p><p>Experiment 1:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e6571eee8ddfb270.q90-58fcafc84d8f9bf6.webp" alt="Experimental Report on Logistics Anomalies"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-14fb58952bc1754b.q90-9bc549081f9743cd.webp" alt="Experimental Report on Logistics Anomalies"></p><p>The Expanded Crucible performs two consecutive reactions:</p><p>Xiranite + Clean Water → Liquid Xiranite</p><p>Liquid Xiranite + Sewage → Xircon Effluent + Inert Xircon Effluent</p><p>Liquid Xiranite is intermediate. Setting its output port produces no fluid output: it goes straight into the second reaction, which operates normally. Its reactant coefficient is 1, so it immediately enters the next reaction when produced.</p><p>Experiment 2:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-04165cda70789d04.q90-722da6d6036ee16e.webp" alt="Experimental Report on Logistics Anomalies"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e1a020b1d73eb88a.q90-5cc63ad8f1964c45.webp" alt="Experimental Report on Logistics Anomalies"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-29ba3042527c4997.q90-64594568f0566457.webp" alt="Experimental Report on Logistics Anomalies"></p><p>This is a half-rate Xircon line. The upper Expanded Crucible performs:</p><p>2*Xircon Effluent + Ferrium Powder → Xircon + Sewage</p><p>Xircon Effluent is supplied by the lower crucible and has coefficient 2. Setting its output port makes it output directly instead of reacting. Effluent enters the second crucible at one unit every 2 seconds. The first unit cannot react and outputs immediately. When the second arrives, the preceding one is already gone, so it still cannot react, and so on.</p><p>Experiment 3:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-883fec225ab608a2.q90-3c9058d991ccb7df.webp" alt="Experimental Report on Logistics Anomalies"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b2351a76ec9f5067.q90-dc4c56f3e5cc76f2.webp" alt="Experimental Report on Logistics Anomalies"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3a35c4cc6e5023a7.q90-1285f8cab9a40f8f.webp" alt="Experimental Report on Logistics Anomalies"></p><p>The upper Expanded Crucible performs multiple reactions:</p><p>Xiranite + Clean Water → Liquid Xiranite</p><p>Liquid Xiranite + Sewage → Xircon Effluent + Inert Xircon Effluent</p><p>Xircon Effluent (internally produced input) + Xircon Effluent (externally supplied input) + Ferrium Powder → Xircon + Sewage</p><p>Effluent for the third reaction comes from two sources: the lower crucible and internal production. Setting an effluent output port outputs it all instead of reacting. External arrival and internal production can almost never be synchronized. Its mean input period is much shorter than the pipe transport period [as stated in the source], so no effluent remains inside the upper crucible to react.</p><p>Experiment 4:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e98761e90cd88b2f.q90-e15ab07dc67c6de8.webp" alt="Experimental Report on Logistics Anomalies"></p><p>In the controlled experiment shown, store effluent in two Fluid Tanks, configure the crucible outputs in advance, and connect pipes to the tanks and crucible. Select the pipes and move them simultaneously to complete the connections. Xircon production is discontinuous and periodic, at 12/min. <span class="mark-red"><em>Cause unknown.</em></span></p><p>In fact, two control ports limit the input. The limited sequence consists of consecutive 1s followed by consecutive 0s, depending on input: starting with full input always gives the first several fluid units consecutively. For example, 12/min gives [1]*2+[0]*18; 24 gives [1]*4+[0]*16; full 30 gives ([1]*5+[0]*15)*n rather than [10]*n. With simultaneous inputs, the crucible accumulates fluid (output 2, input 4/s), reacting whenever two units accumulate.</p><p>Application:</p><p>The logic of Experiment 1 can be used to make a fixed-output “73.75 Xircon” line matching 14.75 SC Wuling Batteries.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d1ce25a766deca70.q90-8a2135cc6e238298.webp" alt="Experimental Report on Logistics Anomalies"></p><p>The production schedule is “figure it out yourself”: three full-rate Xiranite inputs enter below. An 18.4/min Liquid Xiranite input at the lower left gives 73.75/min Xircon; 30/min gives 81/min Xircon. The central objective is consuming all three Liquid Xiranite streams.</p><p>The upper and upper-left Expanded Crucibles are visibly below full rate, unable to consume 30/min Liquid Xiranite, and each has a spare output port. Output their Liquid Xiranite and merge it with the lower-left input into the small crucible to make effluent. Since Liquid Xiranite has reactant coefficient 1, it reacts inside the Expanded Crucibles first, with only the excess output.</p><p>This greatly reduces pipe-component count and avoids the heavy logistics-limit usage of traditional exact splitting of Sewage input.</p><p><span id="source-block-tOFyOuHVkRlm52DPKSRzLd"></span></p><h2 id="experiments-on-claims-of-offline-gas-loss-and-reduced-production-in-cross-region-conduits-and-gas-tanks" tabindex="-1">Experiments on Claims of Offline Gas Loss and Reduced Production in Cross-Region Conduits and Gas Tanks <a class="header-anchor" href="#experiments-on-claims-of-offline-gas-loss-and-reduced-production-in-cross-region-conduits-and-gas-tanks" aria-label="Permalink to &quot;Experiments on Claims of Offline Gas Loss and Reduced Production in Cross-Region Conduits and Gas Tanks&quot;">​</a></h2><p>Consider an extreme case: excess Xiragen at Yinglung Pass needs to be routed to Yinglung Pass to make products. The whole route uses 22 conduit inlets/outlets (partial diagrams below):</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ec999530a61ef2be.q90-627b830b3dd2d641.webp" alt="Experimental Report on Logistics Anomalies"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a70a0872d397f76a.q90-f4e29588407917be.webp" alt="Experimental Report on Logistics Anomalies"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8cfc9c9aaa7b0660.q90-89a945ce5d911005.webp" alt="Experimental Report on Logistics Anomalies"></p><p>First, collect 10026 Xiragen at Yinglung Pass (20 Gas Tanks containing 10000 in total + 26 pipe capacity).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1fb6815f637c8997.q90-a07e9da40040b413.webp" alt="Experimental Report on Logistics Anomalies"></p><p>Next, prepare the same number of Gas Tanks at Marker Stone. An operating mistake added 5+8+9+8-4=26 pipe capacity.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-301d7c5aead6a97d.q90-b00c9f3d112bd189.webp" alt="Experimental Report on Logistics Anomalies"></p><p>Then connect the conduits linking the two locations and immediately log out. Wait 2 hours (only 84 minutes are actually needed).</p><p>Log back in and check the Xiragen in the last Gas Tank:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-60ae80884c93ab7a.q90-5d1894027c4bfd50.webp" alt="Experimental Report on Logistics Anomalies"></p><p>Apart from 26 Xiragen in the extra pipes, nothing was lost! <span class="mark-red"><u><strong>The claim that cross-region conduits + Gas Tanks swallow gas does not hold!</strong></u></span></p></div>',1)])])}const g=i(n,[["render",o]]);export{m as __pageData,g as default};
